<?php

class Node {
    public $char;
    public $index;
    private $nextArray;
    public $hasCul = false;
    public $isSame = false;
    public $nextCount = 0;
    public $nextList = [];
    public $countArray;

    public function __construct($char, $index, $n) {
        $this->char = $char;
        $this->index = $index;
        $this->nextArray = array_fill(0, 26, null);
        $this->countArray = array_fill(0, $n, 0);
    }

    public function __toString() {
        return "" . $this->char;
    }

    public function addNext($index, $node) {
        if ($this->nextArray[$index] === null) {
            $this->nextCount++;
            $this->nextArray[$index] = $node;
            $this->nextList[] = $node;
        }
    }
}

class InputReader {
    private $tokens = [];
    private $pos = 0;
    private $stream;

    public function __construct($stream) {
        $this->stream = $stream;
    }

    /** get next word */
    public function next() {
        while ($this->pos >= count($this->tokens)) {
            $line = fgets($this->stream);
            if ($line === false) {
                throw new Exception("EOF");
            }
            $this->tokens = preg_split('/\s+/', trim($line), -1, PREG_SPLIT_NO_EMPTY);
            $this->pos = 0;
        }
        return $this->tokens[$this->pos++];
    }

    public function nextLong() { return intval($this->next()); }
    public function nextInt() { return intval($this->next()); }
    public function nextDouble() { return floatval($this->next()); }
    public function nextFloat() { return floatval($this->next()); }
}

function find($node) {
    if ($node->hasCul) {
        return;
    }

    $node->countArray[0]++;
    foreach ($node->nextList as $next) {
        find($next);
        $size = count($next->countArray);
        for ($i = 0; $i < $size; $i++) {
            if ($next->countArray[$i] > 0) {
                $node->countArray[$i + 1] += $next->countArray[$i];
            }
        }
    }

    $node->hasCul = true;
}

function main() {
    $inputReader = new InputReader(STDIN);

    $n = $inputReader->nextInt();
    $k = $inputReader->nextLong();
    $str = $inputReader->next();

    $letters = array_fill(0, 26, false);
    $list = [];
    $len = strlen($str);
    for ($i = 0; $i < $len; $i++) {
        $char = $str[$i];
        $node = new Node($char, $i, $n);
        if ($letters[ord($char) - ord('a')]) {
            $node->isSame = true;
        } else {
            $letters[ord($char) - ord('a')] = true;
        }
        $list[] = $node;
    }
    $size = count($list);
    for ($i = 0; $i < $size; $i++) {
        $ai = $list[$i];
        for ($j = $i + 1; $j < $size; $j++) {
            $aj = $list[$j];
            $ai->addNext(ord($aj->char) - ord('a'), $aj);
        }
    }

    foreach ($list as $node) {
        find($node);
    }

    $totalCountArray = array_fill(0, $n, 0);
    for ($i = 0; $i < $n; $i++) {
        foreach ($list as $node) {
            if (!$node->isSame) {
                $totalCountArray[$i] += $node->countArray[$i];
            }
        }
    }

    $totalCost = 0;
    $selectCount = 0;
    for ($i = $n - 1; $i >= 0; $i--) {
        if ($selectCount + $totalCountArray[$i] < $k) {
            $totalCost += ($n - 1 - $i) * $totalCountArray[$i];
            $selectCount += $totalCountArray[$i];
        } else {
            $over = ($selectCount + $totalCountArray[$i]) - $k;
            $totalCost += ($n - 1 - $i) * ($totalCountArray[$i] - $over);
            $selectCount += ($totalCountArray[$i] - $over);
            break;
        }
    }

    if ($selectCount < $k) {
        if ($selectCount == $k - 1) {
            echo ($totalCost + $n) . PHP_EOL;
        } else {
            echo (-1) . PHP_EOL;
        }
    } else {
        echo $totalCost . PHP_EOL;
    }
}

main();
